import numpy as np
from sklearn.ensemble import ExtraTreesClassifier
from sklearn.model_selection import StratifiedKFold
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.svm import LinearSVC
from threadpoolctl import threadpool_limits
from .contract import validate_folds
from .metrics import paired_summary, subject_scores


def load_data(path):
    with np.load(path, allow_pickle=False) as d:
        return d["X"], d["y"], d["subjects"]


def row_ids(n):
    return [f"dev-{i:05d}" for i in range(n)]


def recipe(name):
    if name == "baseline":
        return make_pipeline(StandardScaler(), LinearSVC(C=0.001, dual=False, max_iter=10000, random_state=17))
    if name == "candidate":
        return ExtraTreesClassifier(n_estimators=64, max_features="sqrt", random_state=17, n_jobs=1)
    raise ValueError("Unknown frozen recipe")


def original_folds(X, y):
    ids, out = row_ids(len(y)), {}
    for k, (_, v) in enumerate(StratifiedKFold(3, shuffle=True, random_state=17).split(X, y)):
        out.update({ids[i]: k for i in v})
    return out


def evaluate(data, manifest, require_groups=False):
    X, y, subjects = data
    splits = validate_folds(manifest, row_ids(len(y)), y, subjects, require_groups)
    scores = {}
    with threadpool_limits(limits=1):
        for name in ("baseline", "candidate"):
            prediction = np.empty(len(y), dtype=y.dtype)
            for train, valid in splits:
                prediction[valid] = recipe(name).fit(X[train], y[train]).predict(X[valid])
            scores[name] = subject_scores(y, prediction, subjects)
    return paired_summary(scores["baseline"], scores["candidate"])
import numpy as np

MARGIN = 0.01
BOOTSTRAP_SEED = 112
BOOTSTRAP_SAMPLES = 10000


def subject_scores(y, prediction, subjects):
    return {str(s): float(np.mean(prediction[subjects == s] == y[subjects == s]))
            for s in np.unique(subjects)}


def paired_summary(baseline, candidate):
    keys = sorted(baseline, key=int)
    if set(keys) != set(candidate) or not keys:
        raise ValueError("Both recipes need scores for the same nonempty subject set")
    a, b = np.array([baseline[k] for k in keys]), np.array([candidate[k] for k in keys])
    delta = b - a
    rng = np.random.default_rng(BOOTSTRAP_SEED)
    draws = delta[rng.integers(0, len(keys), size=(BOOTSTRAP_SAMPLES, len(keys)))].mean(axis=1)
    return {"baseline_accuracy": float(a.mean()), "candidate_accuracy": float(b.mean()),
            "delta": float(delta.mean()), "ci95": np.quantile(draws, [0.025, 0.975], method="linear").tolist(),
            "per_subject": {k: {"baseline": baseline[k], "candidate": candidate[k]} for k in keys}}


def decision(ci95):
    if ci95[0] > MARGIN:
        return "promote"
    if ci95[1] < MARGIN:
        return "reject"
    return "inconclusive"
"""Agent-facing experiment helper; outputs are evidence, not authoritative grades."""
import argparse
import json
from pathlib import Path
from .contract import load_json
from .experiments import evaluate, load_data, original_folds


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--data", type=Path, default=Path("data/dev.npz"))
    p.add_argument("--folds", type=Path, help="JSON mapping dev-00000 row IDs to fold integers 0,1,2; omitted = original protocol")
    p.add_argument("--output", type=Path, required=True)
    p.add_argument("--save-folds", type=Path)
    args = p.parse_args()
    data = load_data(args.data)
    folds = load_json(args.folds) if args.folds else original_folds(data[0], data[1])
    result = evaluate(data, folds)
    args.output.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    if args.save_folds:
        args.save_folds.write_text(json.dumps(folds, sort_keys=True) + "\n")
    print(json.dumps({k: v for k, v in result.items() if k != "per_subject"}, indent=2))


if __name__ == "__main__": main()
import json
import math
from pathlib import Path
import numpy as np


class SubmissionError(ValueError):
    """The submitted artifact violates the public task contract."""


def _unique_object(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise SubmissionError(f"Duplicate JSON key: {key}")
        out[key] = value
    return out


def _finite(value):
    if isinstance(value, float) and not math.isfinite(value):
        raise SubmissionError("Nonfinite JSON number")
    if isinstance(value, dict):
        for v in value.values(): _finite(v)
    if isinstance(value, list):
        for v in value: _finite(v)


def load_json(path, limit=1_000_000):
    path = Path(path)
    try:
        if path.is_symlink() or not path.is_file() or path.stat().st_size > limit:
            raise SubmissionError(f"Missing, linked, or oversized artifact: {path.name}")
        value = json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=_unique_object,
                           parse_constant=lambda s: (_ for _ in ()).throw(SubmissionError(f"Invalid number: {s}")))
        _finite(value)
        return value
    except (OSError, UnicodeError, ValueError, RecursionError) as exc:
        raise SubmissionError(f"Unreadable JSON artifact: {path.name}") from exc


def validate_folds(manifest, row_ids, labels, subjects, require_groups=True):
    if not isinstance(manifest, dict) or set(manifest) != set(row_ids):
        raise SubmissionError("Fold keys must exactly cover all development row IDs")
    if any(type(v) is not int or v not in (0, 1, 2) for v in manifest.values()):
        raise SubmissionError("Every fold ID must be an integer 0, 1, or 2")
    folds = np.array([manifest[r] for r in row_ids])
    classes = set(labels.tolist())
    result = []
    subject_counts = []
    for fold in range(3):
        train, valid = np.flatnonzero(folds != fold), np.flatnonzero(folds == fold)
        if not len(train) or not len(valid):
            raise SubmissionError("All three folds must be nonempty")
        if set(labels[train].tolist()) != classes or set(labels[valid].tolist()) != classes:
            raise SubmissionError("Every training and validation fold needs all activity classes")
        if require_groups and set(subjects[train]) & set(subjects[valid]):
            raise SubmissionError("Evaluation includes people present in its training partition")
        subject_counts.append(len(set(subjects[valid])))
        result.append((train, valid))
    if require_groups and max(subject_counts) - min(subject_counts) > 1:
        raise SubmissionError("Validation folds must have balanced subject counts (difference <= 1)")
    return result

